## `fs.preserveTree` mirrors a SOURCE tree (Tup's `!tup_preserve`;
## Typed-Tool-Definitions §Built-In File Operations), and it enumerates that
## tree when the recipe is EVALUATED. A tree generated by another action of
## the same build is therefore read before its producer runs: on a fresh
## checkout the mirror stages nothing and succeeds, and once the producer
## drops a file the next build fails with `preserveTree source file
## disappeared before execution` (seen staging CodeTracer's macOS dmg from
## the `.app` the same build generates). The DSL refuses that shape at
## evaluation, naming the producer and its output, when the producer is one
## of the actions the call orders after.
##
## No mocks: the real action registry, the real `fs.preserveTree` and a real
## source tree in a temporary working directory.

import std/[os, strutils, tempfiles, unittest]

import repro_project_dsl

proc refusal(body: proc()): string =
  ## The message of the `ValueError` `body` raises, or "" when it raises none.
  try:
    body()
  except ValueError as err:
    return err.msg
  ""

suite "preserveTree refuses a source generated in the same graph":
  var root = ""
  var previousDir = ""

  setup:
    resetBuildActionRegistry()
    previousDir = getCurrentDir()
    root = createTempDir("repro-preserve-generated-", "")
    setCurrentDir(root)
    createDir("assets" / "sub")
    writeFile("assets" / "sub" / "a.txt", "a\n")
    createDir("out" / "app" / "bin")
    writeFile("out" / "app" / "bin" / "tool", "previous build\n")

  teardown:
    setCurrentDir(previousDir)
    removeDir(root)

  test "a source root that IS an after action's output":
    let gen = buildAction(id = "gen-app",
      call = inlineExecCall(@["sh", "-c", "generate out/app"]),
      outputs = @["out/app"])
    let msg = refusal(proc() =
      discard fs.preserveTree(sourceRoot = "out/app",
        outputRoot = "out/staging/app", actionId = "stage-app",
        after = @[gen]))
    check "gen-app" in msg
    check "'out/app'" in msg
    check "source" in msg
    check "stage-app" in msg
    # Refused before anything is registered for it.
    for action in registeredBuildActions():
      check action.id != "stage-app"

  test "a source root under an after action's output directory":
    let gen = buildAction(id = "gen-out",
      call = inlineExecCall(@["sh", "-c", "generate out"]),
      declaredOutputs = @["out"])
    let msg = refusal(proc() =
      discard fs.preserveTree(sourceRoot = "out/app",
        outputRoot = "staging/app", after = @[gen]))
    check "gen-out" in msg
    check "'out'" in msg

  test "a source root containing an after action's output":
    let gen = buildAction(id = "gen-tool",
      call = inlineExecCall(@["sh", "-c", "generate out/app/bin/tool"]),
      outputs = @["out/app/bin/tool"])
    let msg = refusal(proc() =
      discard fs.preserveTree(sourceRoot = "./out/app/",
        outputRoot = "staging/app", after = @[gen]))
    check "gen-tool" in msg
    check "'out/app/bin/tool'" in msg

  test "a producer named in deps by action id":
    discard buildAction(id = "gen-by-id",
      call = inlineExecCall(@["sh", "-c", "generate out/app"]),
      outputs = @["out/app"])
    let msg = refusal(proc() =
      discard fs.preserveTree(sourceRoot = "out/app",
        outputRoot = "staging/app", deps = @["gen-by-id"]))
    check "gen-by-id" in msg

  test "a source tree is unaffected":
    # Ordered after an action whose output is elsewhere -- including a
    # sibling whose name merely starts with the source root's.
    let gen = buildAction(id = "gen-elsewhere",
      call = inlineExecCall(@["sh", "-c", "generate"]),
      outputs = @["assets-generated/x", "out/app"])
    var mirrored: BuildActionDef
    let msg = refusal(proc() =
      mirrored = fs.preserveTree(sourceRoot = "assets",
        outputRoot = "staging/assets", actionId = "stage-assets",
        after = @[gen]))
    check msg == ""
    check mirrored.id == "stage-assets"
    check "gen-elsewhere" in mirrored.deps
    check "staging/assets/sub/a.txt" in mirrored.outputs
    check "assets/sub/a.txt" in mirrored.inputs
